html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set parties = (filters.party if filters.party is sequence and filters.party is not string else [filters.party]) | select | list -%}
{%- set accounts = (filters.account if filters.account is sequence and filters.account is not string else [filters.account]) | select | list -%}
{%- set party = parties[0] if parties | length == 1 else None -%}
{%- set account = accounts[0] if accounts | length == 1 and not party else None -%}
{%- set account_type = frappe.db.get_value("Account", account, "account_type") if account else None -%}
{%- set single = party or account -%}
{%- set title = _("Bank Book") if account_type == "Bank" else (_("Cash Book") if account_type == "Cash" else (_("Statement of Account") if single else _("General Ledger"))) -%}
{%- set entries = [] -%}
{%- set totals = [] -%}
{%- for row in data if row is mapping and not row.is_total_row -%}
	{%- if row.voucher_no -%}{%- set ignore = entries.append(row) -%}{%- else -%}{%- set ignore = totals.append(row) -%}{%- endif -%}
{%- endfor -%}
{%- set opening = totals[0] if totals | length >= 3 else None -%}
{%- set closing = totals[-1] if totals else None -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if party %}
	{{ rp.head(title, rp.period(filters.from_date, filters.to_date), rp.party_name(filters.party_type, party), rp.party_meta(filters.party_type, party)) }}
	{%- else %}
	{{ rp.head(title, rp.period(filters.from_date, filters.to_date), rp.short(account, filters.company) if account else None) }}
	{%- endif %}
	{%- if single %}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 84px"><col style="width: 140px"><col style="width: 112px"><col style="width: 112px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Particulars") }}</th>
				<th>{{ _("Voucher Type") }}</th>
				<th>{{ _("Voucher No.") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
				<th class="num">{{ _("Balance") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- if opening and (opening.debit or opening.credit) %}
			<tr>
				<td class="nowrap">{{ rp.date(filters.from_date) }}</td>
				<td>{{ _("Opening Balance") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(opening.debit) }}</td>
				<td class="num">{{ rp.money(opening.credit) }}</td>
				<td class="num">{{ rp.drcr(opening.balance) }}</td>
			</tr>
			{%- endif %}
			{%- set last = namespace(date=None) %}
			{%- for row in entries %}
			{%- set bill = (_("Bill") if (row.against_voucher or row.voucher_no) == row.voucher_no else _("Against Bill")) ~ " " ~ row.bill_no if row.bill_no else None %}
			{%- set narration = [bill, row.remarks if filters.show_remarks else None] | select | join("\n") %}
			<tr{% if narration %} class="has-narration"{% endif %}>
				<td class="nowrap">{% if row.posting_date != last.date %}{{ rp.date(row.posting_date) }}{% endif %}</td>
				<td>
					<span class="muted">{{ _("To") if row.debit else _("By") }}</span>
					{{ rp.short(row.against if (party or account) else (row.party or row.account), filters.company) }}
				</td>
				<td class="clip">{{ rp.vch_type(row) }}</td>
				<td class="nowrap muted">{{ row.voucher_no }}</td>
				<td class="num">{{ rp.money(row.debit) }}</td>
				<td class="num">{{ rp.money(row.credit) }}</td>
				<td class="num">{{ rp.drcr(row.balance) }}</td>
			</tr>
			{%- if narration %}
			<tr class="narration-row">
				<td></td>
				<td class="note narration">{{ narration | e }}</td>
				<td></td>
				<td></td>
				<td></td>
				<td></td>
				<td></td>
			</tr>
			{%- endif %}
			{%- set last.date = row.posting_date %}
			{%- else %}
			<tr><td colspan="7" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if closing %}
			{%- set grand = [closing.debit or 0, closing.credit or 0] | max %}
			<tr class="subtotal">
				<td></td>
				<td>{{ _("Total") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(closing.debit) }}</td>
				<td class="num">{{ rp.money(closing.credit) }}</td>
				<td></td>
			</tr>
			<tr class="subtotal">
				<td></td>
				<td><span class="muted regular">{{ _("To") if closing.balance < 0 else _("By") }}</span> {{ _("Closing Balance") }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(-closing.balance) if closing.balance < 0 else "" }}</td>
				<td class="num">{{ rp.money(closing.balance) if closing.balance > 0 else "" }}</td>
				<td class="num">{{ rp.drcr(closing.balance) }}</td>
			</tr>
			<tr class="total">
				<td></td>
				<td></td>
				<td></td>
				<td></td>
				<td class="num"><span class="double">{{ rp.money(grand) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(grand) }}</span></td>
				<td></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- else %}
	{%- set vouchers = {} %}
	{%- set order = [] %}
	{%- for row in entries %}
	{%- set key = row.posting_date ~ "|" ~ row.voucher_type ~ "|" ~ row.voucher_no %}
	{%- if key not in vouchers %}
	{%- set ignore = vouchers.update({key: {"date": row.posting_date, "first": row, "legs": []}}) %}
	{%- set ignore = order.append(key) %}
	{%- endif %}
	{%- set ignore = vouchers[key]["legs"].append(row) %}
	{%- endfor %}
	<table class="rpf-grid rpf-vouchers">
		<colgroup><col style="width: 80px"><col><col style="width: 140px"><col style="width: 110px"><col style="width: 110px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Account") }}</th>
				<th>{{ _("Voucher") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for key in order %}
			{%- set voucher = vouchers[key] %}
			{%- for leg in voucher.legs | sort(attribute="credit") %}
			<tr class="{{ 'voucher' if loop.first else 'leg' }}">
				<td class="nowrap">{% if loop.first %}{{ rp.date(voucher.date) }}{% endif %}</td>
				<td>
					{{ rp.short(leg.account, filters.company) }}
					{%- if leg.party %} <span class="muted">· {{ leg.party_name or leg.party }}</span>{% endif %}
				</td>
				<td class="clip">
					{%- if loop.first %}{{ rp.vch_type(voucher.first) }}{% if loop.last %} <span class="muted">{{ voucher.first.voucher_no }}</span>{% endif %}
					{%- elif loop.index == 2 %}<span class="muted">{{ voucher.first.voucher_no }}</span>
					{%- if filters.show_remarks and voucher.first.remarks %}<div class="note narration">{{ voucher.first.remarks | e }}</div>{% endif %}
					{%- endif %}
				</td>
				<td class="num">{{ rp.money(leg.debit) }}</td>
				<td class="num">{{ rp.money(leg.credit) }}</td>
			</tr>
			{%- endfor %}
			{%- else %}
			<tr><td colspan="5" class="rpf-empty">{{ _("No transactions in this period") }}</td></tr>
			{%- endfor %}
			{%- if order %}
			<tr class="total">
				<td></td>
				<td colspan="2">{{ _("Total") }} · {{ (_("{0} voucher") if order | length == 1 else _("{0} vouchers")).format(order | length) }}</td>
				<td class="num"><span class="double">{{ rp.money(entries | map(attribute="debit") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(entries | map(attribute="credit") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	<div class="rpf-meta rpf-caption">{{ _("Pick one party or one account in the report filters to print a ledger statement with running balance.") }}</div>
	{%- endif %}
	{{ rp.footnote() }}
</div>
